function Status({ value }: { value: string }) {
  const lower = value.toLowerCase();
  const tone = lower.includes("connected") || lower.includes("indexed") || lower.includes("operational") || lower.includes("active") || lower.includes("resolved") || lower.includes("ready") || lower.includes("online") || lower.includes("passed") || lower.includes("protected")
    ? "bg-[#edf9f4] text-[#16734f]"
    : lower.includes("error") || lower.includes("critical")
      ? "bg-[#fff0f1] text-[#b42337]"
      : lower.includes("pending") || lower.includes("review") || lower.includes("busy") || lower.includes("testing")
        ? "bg-[#fff6e6] text-[#a45a00]"
        : "bg-[#eaf3ff] text-[#0866f5]";
  const Icon = lower.includes("error") || lower.includes("critical") ? AlertTriangle : lower.includes("protected") ? LockKeyhole : Activity;
  return <span className={`status-chip ${tone}`}><Icon className="h-3 w-3" />{value}</span>;
}

function MiniBar({ value, cyan = false }: { value: number; cyan?: boolean }) {
  return <span className="block h-1.5 overflow-hidden rounded-full bg-[#eaf0fa]"><span className="block h-full rounded-full" style={{ width: `${value}%`, background: cyan ? "#16b8e8" : "#0866f5" }} /></span>;
}

function MetricCard({ label, value, detail, icon: Icon, cyan = false }: { label: string; value: string; detail: string; icon: typeof Gauge; cyan?: boolean }) {
  return <article className="fincare-kpi"><div className="flex items-start justify-between"><p className="metric-label">{label}</p><span className={`flex h-8 w-8 items-center justify-center rounded-lg ${cyan ? "bg-[#e6f8fd] text-[#078bb5]" : "bg-[#f4f8ff] text-[#0866f5]"}`}><Icon className="h-4 w-4" /></span></div><p className="mt-5 text-[27px] font-bold leading-none tracking-[-.04em] text-[#071a35]">{value}</p><p className="mt-3 text-[11px] font-medium text-slate-500">{detail}</p><div className="mt-3"><MiniBar value={Math.min(94, Math.max(32, Number.parseFloat(value) || 74))} cyan={cyan} /></div></article>;
}

