function VolumeChart() {
  const points = (key: "total" | "resolved") => trend.map((d, i) => `${48 + i * 88},${182 - ((d[key] - 2500) / 1800) * 130}`).join(" ");
  return <div className="h-[235px] w-full min-w-[600px] pt-3"><svg viewBox="0 0 600 230" role="img" aria-label="Qorebank conversation volume for the past seven days" className="h-full w-full overflow-visible">{[44, 88, 132, 176].map((y) => <line key={y} x1="48" x2="580" y1={y} y2={y} stroke="#e5edf8" strokeDasharray="3 5" />)}<path d="M48 182 L48 133 L136 100 L224 116 L312 70 L400 80 L488 145 L576 103 L576 182 Z" fill="#0866f5" fillOpacity=".055" /><polyline points={points("total")} fill="none" stroke="#0866f5" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" /><polyline points={points("resolved")} fill="none" stroke="#16b8e8" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />{trend.map((d, i) => <g key={d.day}><circle cx={48 + i * 88} cy={182 - ((d.total - 2500) / 1800) * 130} r="4" fill="#fff" stroke="#0866f5" strokeWidth="2.5" /><text x={48 + i * 88} y="214" textAnchor="middle" fill="#718096" fontSize="11" fontWeight="600">{d.day}</text></g>)}</svg></div>;
}

function DataTable({ headers, rows, onRowClick }: { headers: string[]; rows: string[][]; onRowClick?: (row: string[]) => void }) {
  return <div className="overflow-x-auto"><table className="data-table w-full min-w-[760px]"><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={`${row[0]}-${index}`} onClick={() => onRowClick?.(row)} className={onRowClick ? "cursor-pointer" : ""}>{row.map((cell, cellIndex) => <td key={`${cell}-${cellIndex}`} className={cellIndex === 0 ? "font-medium text-[#253b5a]" : ""}>{["Connected", "Pending", "Error", "Testing", "Indexed", "Review due", "Resolved", "Assigned", "Online", "Busy", "Offline", "Active", "Protected", "Ready", "Passed"].includes(cell) ? <Status value={cell} /> : cell}</td>)}</tr>)}</tbody></table></div>;
}

