function AgentWorkspace() {
  const [agentName, setAgentName] = useState("Qorebank Assistant");
  const [welcome, setWelcome] = useState("Hello, I'm Qorebank's AI banking assistant. How can I help you today?");
  const [tone, setTone] = useState("Warm, clear and reassuring");
  const [languages, setLanguages] = useState("English, Yoruba, Igbo, Hausa");
  const utils = trpc.useUtils();
  const agentQuery = trpc.bankPortal.agent.get.useQuery();
  const saveMutation = trpc.bankPortal.agent.save.useMutation({
    onSuccess: async () => {
      await utils.bankPortal.agent.get.invalidate();
      toast("Agent profile saved", { description: "Customer-facing changes are ready for sandbox testing. Protected FinCare policies remain active." });
    },
    onError: (error) => toast("Agent profile could not be saved", { description: error.message }),
  });
  useEffect(() => {
    const config = agentQuery.data;
    if (!config) return;
    setAgentName(config.agentName);
    setWelcome(config.welcomeMessage);
    setTone(config.customerTone);
    setLanguages(config.supportedLanguages);
  }, [agentQuery.data]);
  const save = () => saveMutation.mutate({ agentName, welcomeMessage: welcome, customerTone: tone, supportedLanguages: languages, description: `${agentName} is a Qorebank customer-support assistant, connected only to approved Qorebank systems.` });
  return <div className="app-enter space-y-6"><PageHeader eyebrow="BANK-CONTROLLED CONFIGURATION" title="My AI Agent" description="Configure how Qorebank’s FinCare agent presents itself to customers. Platform safety rules remain protected by FinCare." action="Save changes" onAction={save}><div className="mt-4"><Status value="Operational" /></div></PageHeader><section className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,.75fr)]"><article className="fincare-card p-5"><div className="flex items-center gap-3"><img src={iconLogo} alt="FinCare AI" className="h-11 w-11" /><div><p className="text-sm font-bold text-[#071a35]">Customer-facing presentation</p><p className="mt-1 text-xs text-slate-500">Bank-controlled settings</p></div></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="block"><span className="metric-label">Agent name</span><input value={agentName} onChange={(event) => setAgentName(event.target.value)} className="mt-2 w-full rounded-lg border border-[#dce7f7] bg-white px-3 py-2.5 text-xs text-[#253b5a] outline-none focus:border-[#0866f5]" /></label><label className="block"><span className="metric-label">Customer-facing tone</span><select value={tone} onChange={(event) => setTone(event.target.value)} className="mt-2 w-full rounded-lg border border-[#dce7f7] bg-white px-3 py-2.5 text-xs text-[#253b5a] outline-none focus:border-[#0866f5]"><option>Warm, clear and reassuring</option><option>Concise and professional</option><option>Guided and educational</option></select></label></div><label className="mt-4 block"><span className="metric-label">Welcome message</span><textarea value={welcome} onChange={(event) => setWelcome(event.target.value)} className="mt-2 min-h-[104px] w-full resize-y rounded-lg border border-[#dce7f7] bg-white p-3 text-xs leading-5 text-[#253b5a] outline-none focus:border-[#0866f5]" /></label><label className="mt-4 block"><span className="metric-label">Supported languages</span><div className="mt-2 flex items-center gap-2 rounded-lg border border-[#dce7f7] px-3 py-2.5"><Languages className="h-4 w-4 text-[#0866f5]" /><input value={languages} onChange={(event) => setLanguages(event.target.value)} className="w-full bg-transparent text-xs text-[#253b5a] outline-none" /></div></label><div className="mt-5 rounded-xl border border-[#cfe4fa] bg-[#f4f8ff] p-4"><p className="text-xs font-bold text-[#071a35]">Agent description</p><p className="mt-2 text-xs leading-5 text-[#526e94]">{agentName} is Qorebank’s always-on support assistant, trained on Qorebank product information and connected only to approved Qorebank systems.</p></div></article><aside className="overflow-hidden rounded-xl border border-[#d9e7f8] bg-[#f4f8ff]"><div className="border-b border-[#d9e7f8] bg-white/70 p-5"><div className="flex items-center gap-2"><LockKeyhole className="h-4 w-4 text-[#0866f5]" /><p className="text-sm font-bold text-[#071a35]">FinCare protected policies</p></div><p className="mt-2 text-xs leading-5 text-[#526e94]">These platform safeguards are always enforced and cannot be disabled by a bank administrator.</p></div><div className="space-y-3 p-5">{["Never request PIN, password, OTP or CVV", "No personalised investment advice", "No unsupported product claims", "Protected-data and sensitive-query controls", "Human escalation when policy requires it"].map((policy) => <div key={policy} className="flex items-start gap-3"><span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#e8f8f1] text-[#16734f]"><Check className="h-3 w-3" /></span><p className="text-xs leading-5 text-[#253b5a]">{policy}</p></div>)}</div></aside></section></div>;
}

