function BankConversationsWorkspace() {
  const conversationsQuery = trpc.bankPortal.conversations.list.useQuery();
  const rows = (conversationsQuery.data ?? []).map((conversation) => [conversation.externalReference, conversation.customerReference, conversation.intent, conversation.channel, new Date(conversation.createdAt).toLocaleString(), conversation.escalated ? "Escalated" : "—", conversation.resolutionStatus, conversation.escalated ? "Yes" : "No"]);
  return <div className="app-enter space-y-6"><PageHeader eyebrow="BANK CUSTOMER OPERATIONS" title="Conversations" description="Monitor the customer interactions that arrive through this bank’s configured FinCare channels." action="Export view" onAction={() => toast("Conversation export", { description: "Exports are limited to the active bank environment." })}><div className="mt-4"><Status value={`${rows.length} Active`} /></div></PageHeader><section className="fincare-card overflow-hidden">{rows.length ? <DataTable headers={["Conversation ID", "Customer", "Intent", "Channel", "Started", "Assignment", "Resolution", "Escalated"]} rows={rows} /> : <div className="px-5 py-12 text-center"><MessageCircle className="mx-auto h-8 w-8 text-[#9cb0ca]" /><p className="mt-4 text-sm font-semibold text-[#253b5a]">No bank conversations have arrived yet</p><p className="mt-2 text-xs text-slate-500">Conversations will appear here after a configured bank channel sends them to FinCare.</p></div>}</section></div>;
}

